async function pharmaceuticalIntake(payload) {
  const userContent = JSON.stringify(payload, null, 2);
  const message = await anthropic.messages.create({
    model: "claude-opus-4-5",
    max_tokens: 8192,
    messages: [
      {
        role: "user",
        content: `${SYSTEM_PROMPT2}

Member onboarding health baseline submission:

${userContent}`
      }
    ]
  });
  const block = message.content[0];
  if (!block || block.type !== "text") {
    throw new Error("Claude returned an empty or non-text response");
  }
  const raw = block.text.trim();
  const jsonStr = raw.startsWith("```") ? raw.replace(/^```(?:json)?\n?/, "").replace(/\n?```$/, "").trim() : raw;
  let parsed;
  try {
    parsed = JSON.parse(jsonStr);
  } catch {
    throw new Error(
      `Claude response was not valid JSON: ${jsonStr.slice(0, 300)}`
    );
  }
  const validated = ClinicalPatternReportSchema.safeParse(parsed);
  if (!validated.success) {
    throw new Error(
      `Claude response did not match ClinicalPatternReportSchema: ${JSON.stringify(validated.error.issues)}`
    );
  }
  return validated.data;
}

// src/services/ai/workflowRouter.ts
var WORKFLOWS = {
  health_intake: healthIntake,
  pharmaceutical_intake: pharmaceuticalIntake
};
async function routeWorkflow(workflowType, payload) {
  const handler = WORKFLOWS[workflowType];
  if (!handler) {
    return {
      success: false,
      error: `Unknown workflow_type: "${workflowType}". Registered: ${Object.keys(WORKFLOWS).join(", ")}.`
    };
  }
  try {
    const result = await handler(payload);
    return { success: true, result };
  } catch (err) {
    const message = err instanceof Error ? err.message : String(err);
    return { success: false, error: message };
  }
}

// src/services/pipeline.ts
async function processJob(job) {
  logger.info({ jobId: job.jobId, workflowType: job.workflowType }, "Pipeline: starting job");
  await updateJob(job.jobId, { status: "processing" });
  const outcome = await routeWorkflow(job.workflowType, job.payload);
  if (outcome.success) {
    await updateJob(job.jobId, { status: "completed", result: outcome.result });
    logger.info({ jobId: job.jobId }, "Pipeline: job completed");
  } else {
    await updateJob(job.jobId, { status: "failed", error: outcome.error });
    logger.error({ jobId: job.jobId, error: outcome.error }, "Pipeline: job failed");
  }
}

