  const adminEmail = process.env.ADMIN_EMAIL ?? "daytoheal@yahoo.com";
  const amount = `$${(amount_cents / 100).toFixed(2)}`;
  const payload = JSON.stringify({ stripe_session_id, customer_email, amount, admin_email: adminEmail });
